const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry - Taklamakan Desert region
  const taklamakan = ee.Geometry.Polygon([
    [[78.0, 41.0], [88.0, 41.0], [88.0, 37.0], [78.0, 37.0], [78.0, 41.0]]
  ]);

  // 2. Data Acquisition - MODIS MAIAC AOD
  const getAOD = function(year) {
    const startDate = ee.Date.fromYMD(year, 2, 1);
    const endDate = ee.Date.fromYMD(year, 3, 1);

    return ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
      .filterBounds(taklamakan)
      .filterDate(startDate, endDate)
      .select(['Optical_Depth_055', 'AOD_QA'])
      .map(function(image) {
        // Mask poor quality pixels (bit 0-1: 0=best, 1=good, 2=marginal, 3=bad)
        const qa = image.select('AOD_QA');
        const mask = qa.bitwiseAnd(3).lte(2); // Keep best, good, marginal
        return image.select('Optical_Depth_055').updateMask(mask).multiply(0.001); // Scale factor
      });
  };

  const aod2019 = getAOD(2019);
  const aod2020 = getAOD(2020);

  // Check collection sizes
  const count2019 = aod2019.size().getInfo();
  const count2020 = aod2020.size().getInfo();

  print(`2019 Images: ${count2019}, 2020 Images: ${count2020}`);

  if (count2019 === 0 || count2020 === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Create mean composites and calculate statistics
  const mean2019 = aod2019.mean();
  const mean2020 = aod2020.mean();

  const stats2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taklamakan,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const stats2020 = mean2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: taklamakan,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const meanAOD2019 = stats2019.Optical_Depth_055;
  const meanAOD2020 = stats2020.Optical_Depth_055;
  const pixels2019 = stats2019.Optical_Depth_055_count;
  const pixels2020 = stats2020.Optical_Depth_055_count;

  print(`2019 Mean AOD: ${meanAOD2019?.toFixed(4)}, Pixels: ${pixels2019}`);
  print(`2020 Mean AOD: ${meanAOD2020?.toFixed(4)}, Pixels: ${pixels2020}`);

  // Validation checks
  if (pixels2019 === 0 || pixels2020 === 0) {
    print("<answer>C2</answer>");
    return;
  }

  if (meanAOD2019 === null || meanAOD2020 === null || 
      isNaN(meanAOD2019) || isNaN(meanAOD2020) ||
      meanAOD2019 < 0 || meanAOD2019 > 3 || 
      meanAOD2020 < 0 || meanAOD2020 > 3) {
    print("<answer>C3</answer>");
    return;
  }

  // Final comparison
  if (meanAOD2020 > meanAOD2019) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
